import sys

def solve(n, b, c):
    if n % 2 == 0:
        return -1
    b.sort()
    c.sort()
    b, c = [0] + b, [0] + c
    max_bit = bin(max(b[-1], c[-1])).count('1') - 1
    for i in range(max_bit, -1, -1):
        mask = 2**i
        if i == max_bit:
            found_start = b[0] & mask
        else:
            found_start = None
        for bit_start in range(1, len(b)):
            if (b[bit_start] & mask) != found_start and (b[bit_start-1] & mask) >= found_start:
                return -1
            if b[bit_start] >= c[-1]:
                break

        max_found_end = b[bit_start-1] | (c[bit_start-1] | mask)
        for bit_end in range(c[-1], -1, -1)[::-1]:
            if b[bit_start-1] & (bit_end | mask):
                continue
            next = max_found_end & (1 - (b[bit_start-1] & (b[bit_start] - 1)))
            if next + 1 > b[bit_start] & mask or next < next + 1 and b[bit_start] == c[-1]:
                return -1
            max_found_end = min(max_found_end|(bit_end | mask), next)
    return b

