def extended_euclidean(a, b):
    if b == 0:
        return a, 1, 0
    else:
        gcd, s1, t1 = extended_euclidean(b, a % b)
        s = t1
        t = (s1 - (a // b) * t1)

        return gcd, s, t

def find_solutions(a, gcd_value, mod):
    value = gcd_value * a // gcd
    if value >= 0:
        return [value]
    else:
        return [value + mod for value2 in range(1, mod) for value in find_solutions(value2, gcd_value - value2, mod)]

