import math

def factorial(n):
    return math.factorial(n)

def count_numbers(N, M):
    count = 0
    for i in range(1, int(math.sqrt(N))+1):
        if M == 1:
            break
        if M > i:
            continue
        div = i
        while M / div > 0:
            M %= div
            M -= div
            div -= 1
        if M == 0:
            count += int(N / pow(10, i-1))
    count -= M
    count += N if M == 1 else 0
    return count

T = int(input())
