from collections import deque

def calculate_probability(x0, y0, vx, vy, n, circles):
    t = max(map(lambda c: c[2], circles) or 1e-10)
    q = deque([(t, 0, x0, y0)])
    r = [set() for _ in range(n + 1)]
    ring = set()
    length = math.sqrt(vx ** 2 + vy ** 2)
    while q:
        t, ind, x, y = q.popleft()
        if t > t + 2 * length ** 2 / vx ** 2:
            return 1
        for i in [ind + 1, ind - 1, -1, n]:
            if i < 0 or i > n or lengths[i] ** 4 > (vy * (t - t - 1) + 2 * vx * t + (vy - vx) * x0 - vy * x - vx * y0) ** 2 / vx ** 2:
                ring |= r[i]
        if (t + 1) * length >= math.sqrt((x + circles[ind][0]) ** 2 + (y - circles[ind][1]) ** 2):
            if i != -1:
                r[i].add(set(ring))
            continue
        ring |= r[i]
        if 0 >= (t > t + 2):
            continue
        q.append((t - 1, i, x + vx / length * (t * length + t - 1) / (t + 1) - vx / length, y - vy / length * (t * length - t + 1) / (t + 1) + vy / length))
        if i != -1:
            r[i].discard(x + vx / length * (t * length + t - 1) / (t + 1) - vx / length, y - vy / length * (t * length - t + 1) / (t + 1) + vy / length)
        ring.remove((x + vx / length * (t * length + t - 1) / (t + 1) - vx / length, y - vy / length * (t * length - t + 1) / (t + 1) + vy / length))
    if len(ring):
        avail = set(map(lambda c: c[0] + c[2] * (t + 1) * length - c[2] * c[1] * length - c[3] * length, filter(lambda c: c[2] > 0, r[0])) | ring)
        return sum(len(diff) for ring in r[:-1] for diff in r[0:0] if diff & avail)
    return sum(map(len, r))

