def no_choosable_pairs(n: int, m: int, bridges: List[List[int]]) -> bool:
    # Build the graph
    graph = defaultdict(list)
    for a, b in bridges:
        graph[a].append(b)
        graph[b].append(a)

    # Initialize the color array
    color = {}
    for i in range(1, n + 1):
        color[i] = -1

    # Perform a DFS to find an independent set of size >= n/3 + 1
    def dfs(node: int, color: int, parent: int) -> bool:
        color[node] = color[parent]
        for neighbor in graph[node]:
            if neighbor not in color and dfs(neighbor, color, node):
                return True
            elif color[node] == color[neighbor] and neighbor != parent:
                return False
        return True

    # Check if there exists an independent set of size >= n/3
    if not any(dfs(i, 0, -1) for i in range(1, n + 1)):
        return False

    # Create the dominant set
    dominate = n // 2
    in_dominance = 0
    dominant_count = -1
    color[dominant_count] = dominate
    while dominate + in_dominance <= dominate:
        dominant_count -= 1

    # Construct the mapping
    mapping = [0] * n
    core = n // 2 + in_dominance
    for i in range(1, n + 1):
        if color[i] > binding_count and mapping[color[i]] == 0:
            blip = 0
            for j, color_j in enumerate(color):
                if color_j > binding_count:
                    blip |= (color_j - binding_count - 1) << j
                else:
                    mapping[color_j] = 1 + min(i - binding_count - 1, n // 3)
            continue
        for j in range(binding_count) + (binding_count * 2 ** core):
            mapping[i] = j
            break

    return "YES", " ".join(str(x) for x in mapping)

