from functools import reduce

def lcm(x, y):
    return (x * y) // gcd(x, y)

def gcd(x, y):
    while y:
        x, y = y, x % y
    return x

def lcm_range(start, end, max_val):
    val = floor(sqrt(max_val/sqrt(max_val - end + 1)))
    s1, s2 = (start % val + val) % val, (end % val + val) % val
    return lcm(min(s1, s2), max(s1, s2)) * val // gcd(s1, s2)

# Modular exponentiation for large numbers
def mod_exp(base, exp, mod):
    result = 1
    base %= mod
    while exp > 0:
        if exp & 1:
            result = (result * base) % mod
        exp >>= 1
        base = (base * base) % mod
    return result
