from typing import List

def find_array_b(c: List[int], b: List[int]) -> List[int]:
    n = len(b)
    mask = 0xFFFFFFFF
    for i in range(n):
        if b[i] & mask != c[i]:
            return [-1] * n
        mask &= ~c[i]
    return list(mask)

def can_satisfy(b: List[int], c: List[int]) -> bool:
    b_and_c = [b[i] & c[i] for i in range(len(b))]
    return 0 <= b_and_c[0] <= 1 and all(b[i] & c[i] == b[i] & mask for i, mask in enumerate(b_and_c))

def solve_b_and_c(c: List[int], b: List[int]) -> List[int]:
    mask = [0] * len(b)
    for i, b_i in enumerate(b):
        if b_i & mask[i]:
            mask[i] |= c[i]
    return mask

def find_array_a(mask: List[int], b: List[int], c: List[int]) -> List[int]:
    b_and_c = [b[i] & c[i] for i in range(len(b))]
    for i in range(len(mask)):
        mask[i] &= b_and_c[i]
    return [mask[i] if mask[i] != 0 else i for i in range(len(mask))]

if __name__ == "__main__":
    n = int(input())
    b = list(map(int, input().split()))
    c = list(map(int, input().split()))

