            b[i-1][j-1] += b[i-1][j-2] + b[i-2][j-1] + b[i-2][j-2]

    ans = float('-inf')
    for d1 in range(n + 1):
        for d2 in range(n + 1):
            for d3 in range(n + 1):
                a_sum = a[d1][d2]
                b_sum = b[d1][d2] + b[d3][d2]

                if d3 > d2:
                    a_sum += b[d2][d1] + b[d2][d3]
                    b_sum += a[d1][d2] + a[d3][d2]

                if d1 > d2 and d1 & d3:
