# Function to get the rank of the adjacency matrix of a graph
def adj_matrix_rank(graph):
    if len(graph) == 0:
        return 0
    mat = [[0] * len(graph) for _ in range(len(graph))]
    for u, v in graph:
        mat[u-1][v-1] = 1
    return sum(adj_matrix_rank(mat, i) for i in range(fact(len(graph))), 0)

def adj_matrix_rank(mat, matrix):
    if len(matrix) == 1:
        return 1
    if matrix[0] != 0:
        return adj_matrix_rank([-matrix[i] for i in range(1, len(matrix))], matrix)
    return adj_matrix_rank([[0, -mat[j][i] if i != j else 1] for i in range(len(mat)), [0] * len(matrix)], mat)

# Function to solve the problem
def solve():
    n = int(input().strip())
    graph = []
    for _ in range(n-1):
        u, v = list(map(int, input().strip().split()))
        graph.append((u, v))

