import collections

def max_students_in_the_hospital(N, M, A, B):
    left_to_right_edges = 0
    top_to_left_edges = 0
    left_to_right_edges_count = collections.defaultdict(int)
    top_to_left_edges_count = collections.defaultdict(int)

    for i in range(N):
        a_row = 0
        b_row = 0
        for j in range(M):
            if A[i][j] > 0:
                left_to_right_edges += A[i][j]
                left_to_right_edges_count[(i, j)] = A[i][j]
            if B[i][j] > 0:
                top_to_left_edges_count[(i, j)] = B[i][j]
                top_to_left_edges += B[i][j]

        # Update top-to-right edges
        for (current_row, current_col), count in top_to_left_edges_count.items():
            row_to_row = current_row * N + (current_row + 1) - B[current_row][current_col]
            col_to_col = current_col * N + current_col + 1
            if row_to_row > 0 and col_to_col > 0:
                if row_to_row // N - 1 > left_to_right_edges_count[row_to_row % N]:
                    left_to_right_edges_count[row_to_row % N] += count
                left_to_right_edges_count[row_to_row % N] += count - (N - (row_to_row // N - 1))
                if col_to_col // N - 1 > top_to_left_edges_count[col_to_col % N]:
                    left_to_right_edges_count[col_to_col % N] += count
                left_to_right_edges_count[col_to_col % N] += count - (N - (col_to_col // N - 1))

        # Update bottom-to-right edge for left-to-right edge count
        for (current_row, current_col), count in left_to_right_edges_count.items():
            if current_col + 1 < M:
                next_row_to_right_edge = current_row * N + (current_row + 1) - 1
                bottom_to_right_edge_row = current_row * N + N - 1
                if next_row_to_right_edge > 0 and bottom_to_right_edge_row < next_row_to_right_edge:
                    if next_row_to_right_edge // N - 1 > left_to_right_edges_count[next_row_to_right_edge % N]:
                        left_to_right_edges_count[next_row_to_right_edge % N] += count
                    left_to_right_edges_count[next_row_to_right_edge % N] += count - (N - (next_row_to_right_edge // N - 1))

        top_to_left_edges = 0

    return max(left_to_right_edges, top_to_left_edges)

