def bfs(start, end, duration, durations, queue_used, turn_count):
    if start not in start_transitions:
        return float('inf')
    steps = duration
    dp = {}
    q = deque([(start, deque(), 0, 1)])

    dp[start + duration] = turn_count

    while q:
        current, states, turn_count, start_used = q.popleft()
        if current not in start_transitions:
            dp[current + duration] = min(dp.get(current + duration, float('inf')), start_used + start)
        else:
            for next_element, next_duration in start_transitions[current]:
                next_duration -= duration
                if next_duration < 0:
                    continue
                if turn_count % 2 == 0:
                    bonus = 1
                else:
                    bonus = durations[next_element] - durations[start_element]
                    if bonuses is None or bonus > bonuses:
                        bonuses = bonus
                if dp.get(next_element + next_duration, float('inf')) + start_used < start:
                    if next_element != 'mask':
                        dp[next_element + next_duration] = dp.get(next_element + next_duration, float('inf')) + start_used
                    else:
                        dp[next_element + next_duration] = max(dp.get(next_element + next_duration, float('inf')), dp[current])
                    if current == end:
                        if int(steps) > dp.get(next_element + next_duration, float('inf')):
                            dp[next_element + next_duration] = min(dp[next_element + next_duration], dp[current + duration])
                        if next_duration == 0:
