from collections import defaultdict
import sys

def build_tree():
    n = int(sys.stdin.readline().strip())
    k = int(sys.stdin.readline().strip())
    a = list(map(int, sys.stdin.readline().strip().split()))
    edges = [[] for _ in range(n)]
    for _ in range(n-1):
        ui, vi = map(int, sys.stdin.readline().strip().split())
        edges[ui-1].append(vi-1)
        edges[vi-1].append(ui-1)
    return n, k, a, edges

def find_good_root_and_order(edges, k):
    max_grade = float('-inf')
    for root in range(n):
        for possible_order in get_all_orderings(edges, root, k):
            grade = find_grade(root, a, edges, possible_order)
            max_grade = max(max_grade, grade)
    return max_grade

def get_all_orderings(edges, root, k):
    for ordering in get_orders(edges, root, k):
        yield ordering

def get_orders(edges, root, k):
    if len(edges[root]) <= k:
        yield root
        return
    left = k
    for i in range(n):
        next_node = edges[root].pop(0)
        if left - (len(edges[next_node]) - 1) < 0:
            yield from get_orders(edges, i, k)
            if i != root:
                edges[root].append(next_node)
            continue
        curnodes = 0
        for j in range(n):
            if edges[j].count(root) > 0:
                curnodes += 1
        if curnodes <= len(edges[next_node]):
            yield from get_orders(edges, root, k)
        return

def find_grade(root, a, edges, order):
    neighbors = [n for n in order if edges[root].count(n) > 0 and edges[n].count(root) == 0]
    if len(neighbors) < k:
        return 0
    for i in range(k):
        ai = a[order[i]]
        neighbors.pop(0)
    return ai

if __name__ == "__main__":
    n, k, a, edges = build_tree()
    print(find_good_root_and_order(edges, k))
