import sys

def find_min_gcd(a):
    gcd = 0
    for i in range(1, min(a) + 1):
        cnt = 0
        for j in a:
            if j % i == 0:
                cnt += 1
        if cnt == len(a):
            gcd = i
    return gcd

T = int(sys.stdin.readline())
for _ in range(T):
    N = int(sys.stdin.readline())
    A = list(map(int, sys.stdin.readline().split()))
    M = min(A)  # approximated minimal values
    while found_gcd := find_min_gcd(A) > 1:
        M //= found_gcd
    if M == 1:
        max_goodness = 0
        for i in range(1, N):
            max_goodness += abs(A[i] - A[0])
        max_goodness += 2 * M
        if max_goodness % 2 == 0:
            who_wins = 'Alice'
        else:
            who_wins = 'Bob'
    else:
        who_wins = 'Bob'
    print(who_wins)
