import sys

def find_deputy(city1, city2, deputies):
    for deputy in deputies:
        if deputies[deputy] == city1 and deputies[deputy+2] == city2:
            return deputy + 1
    return None

def distribute_deputies(n, m, cities, bridges):
    deputies = [0] * n
    for i in range(m):
        a, b = bridges[i]
        deputy = find_deputy(cities[a-1], cities[b-1], deputies)
        if deputy is not None:
            deputies[deputy] = b + 1
        else:
            return "NO"
    return "YES\n" + " ".join(map(str, deputies))

# Read input
