            if x == 1 and y == 1:
                break

            elements = [
                x + 1, y + 1,
                x - 1, y + 1,
                x + 1, y - 1,
                x - 1, y - 1,
                x + 2, y,
                x - 2, y,
                x, y + 1,
                x, y - 1
            ]

            elements = (
                ((elements[i] + 3) % k) 
                for i, (v1, v2) in enumerate(
                    ((x, y), (x - 3, y), (x, y - 3))
                )
                for k in range(-1, 2)
                if (0 <= v1 + k < n + 1)
                and (0 <= v2 + k < m + 1)
            )
